"""Turns the app's bundled question banks into supabase/seed.sql.

  python tools/make_seed.py /path/to/quiz_alarm/assets/question_banks

The seed is safe to run more than once: rows are updated in place.
Pictures: 'assets/question_images/x.png' becomes 'seed/x.png', the path the
file should have inside the 'question-images' storage bucket.
"""
import glob
import json
import os
import sys


def q(value):
    """SQL string literal."""
    return "'" + str(value).replace("'", "''") + "'"


def main(folder):
    out = [
        "-- Generated by tools/make_seed.py from the app's bundled banks.",
        "-- Safe to run again: existing rows are updated.",
        "",
    ]
    counts = [0, 0, 0]
    for path in sorted(glob.glob(os.path.join(folder, "*.json"))):
        data = json.load(open(path, encoding="utf-8"))
        unit = data["unit"]
        counts[0] += 1
        out.append(
            "insert into public.units (id, name, description, sort_order) values "
            f"({q(unit['id'])}, {q(unit['name'])}, {q(unit.get('description', ''))}, "
            f"{int(unit.get('order', 0))})\n"
            "  on conflict (id) do update set name = excluded.name, "
            "description = excluded.description, sort_order = excluded.sort_order;"
        )
        for t_index, topic in enumerate(data["topics"]):
            counts[1] += 1
            out.append(
                # "access" is only set when the topic is new: who can use a
                # topic is afterwards decided on the admin site.
                "insert into public.topics (id, unit_id, name, sort_order, access) values "
                f"({q(topic['id'])}, {q(unit['id'])}, {q(topic['name'])}, {t_index}, "
                f"{q(topic.get('access', 'paid'))})\n"
                "  on conflict (id) do update set unit_id = excluded.unit_id, "
                "name = excluded.name, sort_order = excluded.sort_order;"
            )
            for question in topic.get("questions", []):
                counts[2] += 1
                image = question.get("image", "")
                if image:
                    image = "seed/" + os.path.basename(image)
                out.append(
                    "insert into public.questions (id, topic_id, type, text, options, "
                    "answer, alt_answers, explanation, image_path, source) values\n  ("
                    + ", ".join(
                        [
                            q(question["id"]),
                            q(topic["id"]),
                            q("mcq" if question["type"] == "mcq" else "saq"),
                            q(question["text"].strip()),
                            q(json.dumps(question.get("options", []), ensure_ascii=False)) + "::jsonb",
                            q(question["answer"].strip()),
                            q(json.dumps(question.get("alt_answers", []), ensure_ascii=False)) + "::jsonb",
                            q(question.get("explanation", "")),
                            q(image),
                            "'seed'",
                        ]
                    )
                    + ")\n  on conflict (id) do update set topic_id = excluded.topic_id, "
                    "type = excluded.type, text = excluded.text, options = excluded.options, "
                    "answer = excluded.answer, alt_answers = excluded.alt_answers, "
                    "explanation = excluded.explanation, image_path = excluded.image_path;"
                )
        out.append("")
    dest = os.path.join(os.path.dirname(__file__), "..", "supabase", "seed.sql")
    open(dest, "w", encoding="utf-8").write("\n".join(out))
    print(f"{counts[0]} units, {counts[1]} topics, {counts[2]} questions -> supabase/seed.sql")


if __name__ == "__main__":
    main(sys.argv[1] if len(sys.argv) > 1 else "../quiz_alarm/assets/question_banks")
